&= \frac{\begin{pmatrix} a \\ \frac{5}{2} a + 4 \end{pmatrix} \cdot \begin{pmatrix} c \\ d \end{pmatrix}}{\left\| \begin{pmatrix} c \\ d \end{pmatrix} \right\|^2} \begin{pmatrix} c \\ d \end{pmatrix} \\
