CC = D + D + D - A - A;
BB = reflect(A,M)*B;
EE = reflect(A,M)*D;
draw(M--A--BB--CC--A--B--C--A);
label("$M$",M,SE);
label("$A$",A,N);
label("$B$",B,SW);
label("$C$",C,SE);
label("$C'$",CC,S);
label("$B'$",BB,E);
label("$D$",D,NW);
label("$E$",EE,N);
